add('l019-sector-laggard-warning','同一板块中第二龙头的补涨比第一龙头更有力时，作者将其视为该板块往往要进入调整的标志。','0091:011',['板块轮动','调整','补涨'],conditions=['比较同板块第一与第二龙头','第二龙头补涨力度超过第一龙头'],note='二次复读明确“往往”与作者经验规则性质，未改写为必然转折。')
add('l019-internal-divergence-watch','观察上涨背驰出货时，除比较两段趋势的力度，还应观察第二段趋势内部背驰；两段之间为狭窄平台整理时尤其如此。','0093:001',['背驰','趋势','盘整'],conditions=['上涨中观察背驰','尤其两趋势间为狭窄平台整理'],note='复读b000作者头；提取方法条件，保留“平台后调整往往快跌”的经验性而非确定性。')
add('l019-ipo-first-buy-prerequisite','新股在日线没有经过大幅下跌时，不会出现日线第一类买点，也不会有日线第二类买点；小级别仍可能出现。','0093:006',['次新股','第一类买点','第二类买点','级别'],conditions=['新股','日线尚无大幅下跌'],exceptions=['小级别可能有第一二类买点','开盘后即上涨的新股一般只会有第三类买点'],note='二次复读b005作者头，明确限定日线而非否认所有级别的买点。')
add('l019-gap-types','作者区分缺口性质：强烈上涨后及盘整中的缺口会回补，而突破性缺口在趋势完成前不会回补。','0096:004',['缺口','趋势','盘整'],conditions=['按缺口出现的结构位置分类'],note='二次复读b003作者头，保存为作者缺口判断规则；没有推广为所有缺口必回补。')
