add('l020-trend-wave-disjoint','趋势中前后同级别中枢不能有任何重叠，这也包括围绕中枢产生的瞬间波动区间之间的重叠。','0097:008',['趋势','走势中枢','波动区间'],conditions=['趋势','前后同级别中枢'],note='独立复读正文并视觉核对PDF97页；明确条件扩及外围波动，不能仅比较中枢核心区间。')
add('l020-expansion-touch','新的三段次级别重叠区间虽然不与原中枢重叠，只要围绕新中枢的波动触及原中枢延续时的某个瞬间波动区间，就产生更大级别中枢。','0097:008',['中枢扩张','走势中枢','波动区间'],conditions=['新旧中枢核心区间不重叠','外围波动区间重叠'],relations=[('中枢扩张','波动区间','requires')])
